DROP TABLE IF EXISTS `jemaat`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8mb4 */;
CREATE TABLE `jemaat` (
  `id_jemaat` int(11) NOT NULL AUTO_INCREMENT,
  `nia` char(8) NOT NULL,
  `nama_jemaat` varchar(255) NOT NULL,
  `gender` enum('L','P') DEFAULT NULL,
  `telepon` varchar(255) DEFAULT NULL,
  `asal_gereja` varchar(255) DEFAULT NULL,
  `tanggal_terdaftar` date DEFAULT NULL,
  `tempat_lahir` varchar(255) DEFAULT NULL,
  `tanggal_lahir` date DEFAULT NULL,
  `tanggal_baptis` date DEFAULT NULL,
  `tanggal_sidi` date DEFAULT NULL,
  `tanggal_nikah` date DEFAULT NULL,
  `status_aktif` enum('Aktif','Meninggal Dunia','Atestasi Keluar','Pindah Gereja','Bukan Anggota','Pasif','Tidak Aktif') DEFAULT NULL,
  `status_menikah` enum('Menikah','Belum Menikah','Lainnya') DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `deleted_at` datetime DEFAULT NULL,
  `updated_by` varchar(100) DEFAULT NULL,
  `keterangan` varchar(100) DEFAULT NULL,
  PRIMARY KEY (`id_jemaat`),
  UNIQUE KEY `unique_no_anggota` (`nia`)
) ENGINE=InnoDB AUTO_INCREMENT=1702 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `jemaat`
--

LOCK TABLES `jemaat` WRITE;
/*!40000 ALTER TABLE `jemaat` DISABLE KEYS */;
